import ai.onnxruntime.*;
import java.util.Map;

public final class RequestPath {
  static float score(OrtEnvironment env, OrtSession session, float[] features) throws OrtException {
    try (OnnxTensor input = OnnxTensor.createTensor(env, new float[][] {features});
         OrtSession.Result result = session.run(Map.of("features", input))) {
      return ((float[][]) result.get(0).getValue())[0][0];
    }
  }
  public static void main(String[] args) throws Exception {
    OrtEnvironment env = OrtEnvironment.getEnvironment();
    try (OrtSession.SessionOptions options = new OrtSession.SessionOptions()) {
      options.addCUDA(0);
      options.setIntraOpNumThreads(1);
      System.out.println("availableProviders=" + OrtEnvironment.getAvailableProviders());
      try (OrtSession session = SessionFactory.open(env, args[0], options)) {
        System.out.println(score(env, session, new float[] {1, 2, 3, 4}));
      }
    }
  }
}

